def countSubstring(S: str) -> int:
    balance = 0
    count = 0
    prefix_balance = {0: 1}

    for char in S:
        if char == '1':
            balance += 1
        else:
            balance -= 1

        if balance in prefix_balance:
            prefix_balance[balance] += 1
        else:
            prefix_balance[balance] = 1

        for key in prefix_balance:
            if key < balance:
                count += prefix_balance[key]

    return count
